/**
 * Defaults `--app-sys-id` from the current directory's `now.config.json` (`scopeId`) when neither
 * `--scope` nor `--app-sys-id` was provided. A Fluent project always knows its own app's sys_id this
 * way, so app-repo commands run from inside the project don't need it passed on every invocation.
 * Throws a clear error if no Fluent project is detected (no `now.config.json`, and no `now` field in
 * `package.json`) — there's nothing to default from in that case.
 */
export declare function resolveAppSysIdFromNowConfig(cwd?: string): string;
/**
 * Defaults `--app-version` from the current directory's `package.json` (`version`), when not
 * explicitly provided. Unlike `resolveAppSysIdFromNowConfig`, this is a soft default — `--app-version`
 * is optional on both `install` and `publish` (each has its own sensible fallback when omitted), so a
 * missing/unreadable `package.json` just means "nothing to default," not an error.
 */
export declare function resolveAppVersionFromPackageJson(cwd?: string): string | undefined;
